from dataclasses import asdict, dataclass
import json
from pathlib import Path

@dataclass
class Expense:
    category: str
    amount: float
    note: str = ""

class ExpenseLedger:
    def __init__(self):
        self.entries = []

    def add(self, category, amount, note=""):
        if amount <= 0:
            raise ValueError(f"Amount must be positive, got {amount}")
        clean_cat = category.strip().lower()
        self.entries.append(Expense(clean_cat, round(float(amount), 2), note.strip()))

    def total(self):
        return round(sum(e.amount for e in self.entries), 2)

    def by_category(self):
        totals = {}
        for e in self.entries:
            totals[e.category] = round(totals.get(e.category, 0.0) + e.amount, 2)
        return totals

    def save_json(self, path):
        data = [asdict(e) for e in self.entries]
        with Path(path).open("w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)

    @classmethod
    def load_json(cls, path):
        with Path(path).open("r", encoding="utf-8") as f:
            raw = json.load(f)
        ledger = cls()
        for row in raw:
            ledger.add(row["category"], row["amount"], row.get("note", ""))
        return ledger

ledger = ExpenseLedger()
ledger.add("Food", 14.50, "Lunch")
ledger.add("Books", 32.00, "Python guide")
ledger.add("food", 6.25, "Coffee")

ledger_file = Path("ledger.json")
ledger.save_json(ledger_file)
reloaded = ExpenseLedger.load_json(ledger_file)

assert reloaded.total() == 52.75
assert reloaded.by_category() == {"food": 20.75, "books": 32.0}

print(f"Total spent: ${reloaded.total():.2f}")
for cat, amt in reloaded.by_category().items():
    print(f"  - {cat:<8}: ${amt:.2f}")

